  'ref.cat.delai': { fr: 'Délai propre de fin (jours ouvrables)', nl: 'Eigen eindtermijn (werkdagen)' },
  'ref.cat.delai.help': { fr: 'Facultatif. Remplace le délai de fin de la priorité quand celle-ci compte en jours ouvrables ; vide, le délai de la priorité s’applique.', nl: 'Optioneel. Vervangt de eindtermijn van de prioriteit wanneer die in werkdagen telt; leeg geldt de termijn van de prioriteit.' },
  'ref.cat.en_vigueur': { fr: 'En vigueur', nl: 'Geldend' },
  'ref.cat.desactiver': { fr: 'Désactiver la catégorie', nl: 'De categorie deactiveren' },
  'ref.cat.desactiver.help': { fr: 'Une catégorie désactivée n’est plus proposée aux demandeurs ; les demandes qui la portent la gardent. Un domaine se désactive après ses natures.', nl: 'Een gedeactiveerde categorie wordt niet meer aan de aanvragers voorgesteld; de aanvragen die ze dragen behouden ze. Een domein wordt na zijn soorten gedeactiveerd.' },
  'ref.cat.desactiver.confirm': { fr: 'Désactiver cette catégorie ?', nl: 'Deze categorie deactiveren?' },
