  'ref.cal.feries': { fr: 'Jours fériés légaux', nl: 'Wettelijke feestdagen' },
  'ref.cal.feries.help': { fr: 'Les dix jours fériés légaux belges, calculés chaque année ; ils ne se modifient pas.', nl: 'De tien wettelijke Belgische feestdagen, elk jaar berekend; ze kunnen niet worden gewijzigd.' },
  'ref.cal.annee': { fr: 'Année', nl: 'Jaar' },
  'ref.cal.jours': { fr: 'Congés et fermetures de l’entité', nl: 'Verlofdagen en sluitingen van de entiteit' },
  'ref.cal.jours.help': { fr: 'Les congés reviennent chaque année à la même date ; une fermeture couvre une période. Ces jours ne comptent pas dans les délais. Désactivé, un jour redevient ouvrable pour les délais suivants.', nl: 'De verlofdagen komen elk jaar op dezelfde datum terug; een sluiting beslaat een periode. Die dagen tellen niet mee in de termijnen. Gedeactiveerd telt een dag opnieuw mee voor de volgende termijnen.' },
