  'ref.cal.desactiver': { fr: 'Désactiver', nl: 'Deactiveren' },
  'ref.cal.desactiver.help': { fr: 'Le jour redevient ouvrable pour les délais calculés ensuite.', nl: 'De dag telt opnieuw mee voor de termijnen die daarna worden berekend.' },
  'ref.cal.desactiver.confirm': { fr: 'Désactiver ce jour ?', nl: 'Deze dag deactiveren?' },
  'ref.cal.reactiver': { fr: 'Réactiver', nl: 'Heractiveren' },
  'ref.sim.question': { fr: 'Une demande reçue…', nl: 'Een aanvraag ontvangen…' },
  'ref.sim.intro': { fr: 'Calcule quand une demande doit être prise en charge et terminée, avec l\'horaire, les jours fériés, les congés et les fermetures de l\'entité, à l\'heure de Bruxelles. Rien n\'est enregistré.', nl: 'Berekent wanneer een aanvraag ten laste genomen en afgerond moet zijn, met het uurrooster, de feestdagen, de verlofdagen en de sluitingen van de entiteit, volgens de Brusselse tijd. Er wordt niets opgeslagen.' },
  'ref.sim.selon': { fr: 'Selon', nl: 'Volgens' },
