  'ref.sim.recu': { fr: 'Reçue le', nl: 'Ontvangen op' },
  'ref.sim.calculer': { fr: 'Calculer', nl: 'Berekenen' },
  'ref.sim.resultat': { fr: '… est à traiter', nl: '… moet worden behandeld' },
