  'listes.field.ordre.help': { fr: "Les plus petits nombres viennent en tête. Laissé vide, la valeur se range à la fin.", nl: 'De kleinste getallen komen eerst. Leeg gelaten komt de waarde achteraan.' },
  'listes.field.code': { fr: 'Code technique', nl: 'Technische code' },
  'listes.field.code.help': { fr: 'Minuscules, chiffres et souligné. Laissé vide, il se tire du libellé français. Il ne change plus ensuite.', nl: 'Kleine letters, cijfers en underscore. Leeg gelaten wordt hij uit het Franse label afgeleid. Hij wijzigt daarna niet meer.' },
  'listes.deactivate': { fr: 'Désactiver cette valeur', nl: 'Deze waarde deactiveren' },
  'listes.deactivate.help': { fr: "La valeur ne sera plus proposée. Les lieux qui la portent la gardent.", nl: 'De waarde wordt niet meer voorgesteld. De plaatsen die ze dragen behouden ze.' },
  'listes.deactivate.confirm': { fr: 'Désactiver cette valeur ? Elle peut être réactivée.', nl: 'Deze waarde deactiveren? Ze kan opnieuw worden geactiveerd.' },
